package dao.staff;

import config.DatabaseConnection;
import java.sql.*;
import java.util.ArrayList;
import java.util.List;
import model.staff.StaffModels.*;

public final class StaffDAO {
    public List<Option> departments(){return options("SELECT MaBoPhan,TenBoPhan FROM dbo.BoPhan WHERE TrangThai=N'HoatDong' ORDER BY TenBoPhan");}
    public List<Option> titles(){return options("SELECT MaChucDanh,TenChucDanh FROM dbo.ChucDanh ORDER BY TenChucDanh");}
    public List<Option> specialties(){return options("SELECT MaChuyenKhoa,TenChuyenKhoa FROM dbo.ChuyenKhoa WHERE TrangThai=N'HoatDong' ORDER BY TenChuyenKhoa");}
    public List<Staff> find(String q,boolean doctorOnly){String sql="SELECT n.MaNhanVien,n.HoTen,n.NgaySinh,n.GioiTinh,n.SoDienThoai,n.Email,n.DiaChi,n.NgayBatDau,n.TrangThaiCongTac,n.MaBoPhan,bp.TenBoPhan,n.MaChucDanh,cd.TenChucDanh,CASE WHEN bs.MaNhanVien IS NULL THEN 0 ELSE 1 END,bs.HocVi,bs.ChuyenMon,bs.MaChuyenKhoa,bs.ChungChiHanhNghe,n.AnhDaiDien FROM dbo.NhanVien n LEFT JOIN dbo.BoPhan bp ON bp.MaBoPhan=n.MaBoPhan LEFT JOIN dbo.ChucDanh cd ON cd.MaChucDanh=n.MaChucDanh LEFT JOIN dbo.BacSi bs ON bs.MaNhanVien=n.MaNhanVien WHERE (?='' OR n.MaNhanVien LIKE ? OR n.HoTen LIKE ? OR n.SoDienThoai LIKE ?) AND (?=0 OR bs.MaNhanVien IS NOT NULL) ORDER BY n.HoTen";List<Staff>x=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql)){String k=q==null?"":q.trim();s.setString(1,k);s.setString(2,"%"+k+"%");s.setString(3,"%"+k+"%");s.setString(4,"%"+k+"%");s.setInt(5,doctorOnly?1:0);try(ResultSet r=s.executeQuery()){while(r.next())x.add(new Staff(r.getString(1),r.getString(2),date(r.getDate(3)),r.getString(4),r.getString(5),r.getString(6),r.getString(7),date(r.getDate(8)),r.getString(9),r.getString(10),r.getString(11),r.getString(12),r.getString(13),r.getBoolean(14),r.getString(15),r.getString(16),r.getString(17),r.getString(18),r.getString(19)));}return List.copyOf(x);}catch(SQLException e){throw err("tải danh sách nhân sự",e);}}
    public void save(StaffDraft d,boolean doctor){String insert="INSERT INTO dbo.NhanVien(MaNhanVien,HoTen,NgaySinh,GioiTinh,SoDienThoai,Email,DiaChi,NgayBatDau,TrangThaiCongTac,MaBoPhan,MaChucDanh,AnhDaiDien) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)";String update="UPDATE dbo.NhanVien SET HoTen=?,NgaySinh=?,GioiTinh=?,SoDienThoai=?,Email=?,DiaChi=?,NgayBatDau=?,TrangThaiCongTac=?,MaBoPhan=?,MaChucDanh=?,AnhDaiDien=? WHERE MaNhanVien=?";try(Connection c=DatabaseConnection.getConnection()){c.setAutoCommit(false);try{boolean exists;try(PreparedStatement q=c.prepareStatement("SELECT 1 FROM dbo.NhanVien WHERE MaNhanVien=?")){q.setString(1,d.id());try(ResultSet r=q.executeQuery()){exists=r.next();}}try(PreparedStatement s=c.prepareStatement(exists?update:insert)){int i=1;if(!exists)s.setString(i++,d.id());s.setNString(i++,d.name());setDate(s,i++,d.birth());s.setNString(i++,d.gender());s.setString(i++,d.phone());s.setString(i++,d.email());s.setNString(i++,d.address());setDate(s,i++,d.startDate());s.setNString(i++,d.status());s.setString(i++,d.departmentId());s.setString(i++,d.titleId());s.setString(i++,d.avatarPath());if(exists)s.setString(i,d.id());s.executeUpdate();}if(doctor){String bs="MERGE dbo.BacSi AS t USING (SELECT ? AS MaNhanVien) AS s ON t.MaNhanVien=s.MaNhanVien WHEN MATCHED THEN UPDATE SET HocVi=?,ChuyenMon=?,MaChuyenKhoa=?,ChungChiHanhNghe=? WHEN NOT MATCHED THEN INSERT(MaNhanVien,HocVi,ChuyenMon,MaChuyenKhoa,ChungChiHanhNghe) VALUES(?,?,?,?,?);";try(PreparedStatement s=c.prepareStatement(bs)){s.setString(1,d.id());s.setNString(2,d.degree());s.setNString(3,d.specialty());s.setString(4,d.specialtyId());s.setNString(5,d.license());s.setString(6,d.id());s.setNString(7,d.degree());s.setNString(8,d.specialty());s.setString(9,d.specialtyId());s.setNString(10,d.license());s.executeUpdate();}}c.commit();}catch(Exception e){try{c.rollback();}catch(SQLException x){e.addSuppressed(x);}throw e;}finally{try{c.setAutoCommit(true);}catch(SQLException ignored){}}}catch(Exception e){throw err("lưu hồ sơ nhân sự",e);}}
    private static List<Option> options(String sql){List<Option> result=new ArrayList<>();try(Connection c=DatabaseConnection.getConnection();PreparedStatement s=c.prepareStatement(sql);ResultSet r=s.executeQuery()){while(r.next())result.add(new Option(r.getString(1),r.getString(2)));return List.copyOf(result);}catch(SQLException e){throw err("tải danh mục nhân sự",e);}}
    private static void setDate(PreparedStatement s,int i,java.time.LocalDate d)throws SQLException{if(d==null)s.setNull(i,Types.DATE);else s.setDate(i,Date.valueOf(d));}
    private static java.time.LocalDate date(Date d){return d==null?null:d.toLocalDate();}
    private static StaffDAOException err(String op,Exception e){return new StaffDAOException("Không thể "+op+". Chi tiết hệ thống: "+e.getMessage(),e);}
}
